    print('slides', len(prs.slides))
    for i, slide in enumerate(prs.slides, 1):
        texts = []
        for shape in slide.shapes:
            if hasattr(shape, 'text'):
                t = shape.text.strip().replace('\n',' | ')
                if t:
                    texts.append(t)
        joined = ' || '.join(texts)
